int score = 7;
if (score < 0) {
    System.out.println("invalid");
} else if (score >= 6) {
    System.out.println("pass");
} else {
    System.out.println("retry");
}

int choice = 2;
switch (choice) {
    case 1:
        System.out.println("first");
        break;
    case 2:
        System.out.println("middle");
        break;
    default:
        System.out.println("other");
}

int sum = 0;
int count = 0;
for (int i = 1; i <= 5; i++) {
    if (i % 2 != 0) {
        sum += i;
        count++;
    }
}
System.out.println(sum + " " + count);

int found = -1;
for (int i = 1; i <= 6; i++) {
    if (i % 4 == 0) {
        found = i;
        break;
    }
}
System.out.println(found);
